authored.REQ-0001:
def decide(trace):
    from specflow.refmodel.temporal import after, worst

    supported = {1, 2, 4, 8}

    def row_value(row, port):
        return row['outputs'].get(port, row['inputs'].get(port))

    def holds(row, cond):
        return all(row_value(row, port) == value for port, value in cond.items())

    def any_condition(conditions):
        return lambda row: any(holds(row, condition) for condition in conditions)

    opens = lambda row: (
        row_value(row, 'ena') == 1
        and row_value(row, 'cmd') in supported
        and row_value(row, 'active_command') == 1
    )
    closes = lambda row: row_value(row, 'cmd_ack') == 1
    aborts = any_condition([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    windows = after(trace, opens, until=closes, aborts=aborts)
    verdicts = []

    for window in windows:
        rows = window.rows
        if not rows:
            verdicts.append((None, window.edge, 'no post-activation SDA-control state was observed'))
            continue

        # effect_follows is true for the normalized activation: inspect only
        # distinct states after the active-command trigger.
        trigger_index = rows[0]['index']
        post = [row for row in rows if row['index'] > trigger_index]
        cmd = window.value('cmd')
        din = window.value('din')

        if cmd == 1:  # START: SDA is driven low.
            match = next((row for row in post if row_value(row, 'sda_oen') == 0), None)
            if match is not None:
                verdicts.append((True, match['edge'], 'START sequence drives sda_oen low'))
            elif window.closed:
                verdicts.append((False, window.edge, 'START sequence never drives sda_oen low'))
            else:
                verdicts.append((None, window.edge, 'START window ended before SDA drive was observed'))

        elif cmd == 2:  # STOP: SDA is driven low, then released high.
            low = next((row for row in post if row_value(row, 'sda_oen') == 0), None)
            high = None
            if low is not None:
                high = next(
                    (row for row in post
                     if row['index'] > low['index'] and row_value(row, 'sda_oen') == 1),
                    None)
            if high is not None:
                verdicts.append((True, high['edge'], 'STOP sequence drives SDA low and then releases it'))
            elif window.closed:
                verdicts.append((False, window.edge, 'STOP sequence did not drive SDA low and then release it'))
            else:
                verdicts.append((None, window.edge, 'STOP window ended before the SDA sequence was observed'))

        elif cmd == 4:  # WRITE: din=0 drives low; din=1 releases high.
            expected = 0 if din == 0 else 1
            match = next((row for row in post if row_value(row, 'sda_oen') == expected), None)
            if match is not None:
                verdicts.append((True, match['edge'], f'WRITE din={din} selects sda_oen={expected}'))
            elif window.closed:
                verdicts.append((False, window.edge, f'WRITE din={din} never produces sda_oen={expected}'))
            else:
                verdicts.append((None, window.edge, 'WRITE window ended before SDA control was observed'))

        elif cmd == 8:  # READ: SDA is released for the read window.
            match = next((row for row in post if row_value(row, 'sda_oen') == 1), None)
            if match is not None:
                verdicts.append((True, match['edge'], 'READ sequence releases SDA'))
            elif window.closed:
                verdicts.append((False, window.edge, 'READ sequence never releases SDA'))
            else:
                verdicts.append((None, window.edge, 'READ window ended before SDA release was observed'))

    return worst(verdicts)

authored.REQ-0003:
def decide(trace):
    if not trace:
        return (None, None, 'no clock-edge samples were provided')

    for row in trace:
        outputs = row.get('outputs', {})
        if outputs.get('scl_o') != 0:
            return (False, row.get('edge'), 'scl_o is not the required constant low open-drain drive value')
        if outputs.get('sda_o') != 0:
            return (False, row.get('edge'), 'sda_o is not the required constant low open-drain drive value')

    return (True, None, 'scl_o and sda_o remain constant low across all sampled states; cmd_ack is not constrained by this requirement')

