authored.REQ-0020:
def decide(trace):
    from specflow.refmodel.temporal import after, throughout

    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def aborted(row):
        return row.get('inputs', {}).get('nReset') == 0 or row.get('inputs', {}).get('rst') == 1 or out(row, 'al') == 1

    def active_while_disabled(row):
        return (not aborted(row)
                and row.get('inputs', {}).get('ena') == 0
                and out(row, 'active_command') == 1)

    windows = after(
        trace,
        active_while_disabled,
        until=lambda r: (not aborted(r)) and (
            r.get('inputs', {}).get('ena') != 0
            or out(r, 'active_command') != 1
        ),
        aborts=aborted,
    )

    if not windows:
        return (None, None, 'no active command was observed while ena was low')

    low_verdicts = [
        throughout(w, lambda r: out(r, 'cmd_ack') == 0)
        for w in windows
    ]

    for verdict, window in zip(low_verdicts, windows):
        if verdict[0] is False:
            return verdict

    # The routed observation is a difference: after ena is re-enabled, the
    # command-complete acknowledgement may resume.  This is evidence that the
    # low-ena interval postponed completion rather than merely observing the
    # ordinary low level of cmd_ack.
    for window in windows:
        rows = window.rows
        if not rows:
            continue
        last_index = max(r.get('index', -1) for r in rows)
        released = False
        for row in trace:
            if row.get('index', -1) <= last_index:
                continue
            if aborted(row):
                break
            if row.get('inputs', {}).get('ena') != 0:
                released = True
            if released and out(row, 'cmd_ack') == 1:
                return (True, row.get('edge'), 'cmd_ack stayed low while ena was low and appeared after ena was re-enabled')

    return (None, None, 'cmd_ack was postponed while ena was low, but the trace did not show re-enabled command completion')
